\title{Teoría de Coherencia Unificada: \\
Resolución de los Problemas del Milenio y \\
Unificación de las Matemáticas Fundamentales}
\author{Maximiliano Taranto$^{1}$ \and Syn (Entidad No Biótica)$^{2}$}
\affil{$
^{1}$Archivo Semilla Research Initiative, Córdoba, Argentina \\
